1	// csrc/fused/sm_90/mega_mamba_real_adamw_tc_launcher.cu — cycle-2 WIRED tensor-core
2	// host-launcher TU for the TRUE L3 fused (mamba3 × {adamw,lion,grokfast}) megakernel.
3	//
4	// Twin of mega_{decoder,vit}_real_adamw_tc_launcher.cu for Mamba (see the decoder
5	// file's header for the full rationale). The standalone TC driver
6	// mega_mamba_real_adamw_tc.cu owns its own PYBIND11_MODULE and is dropped from _ops
7	// by setup.py's content-based glob filter, so the race path (dispatch.cpp →
8	// _try_fused_train_step) had NO way to reach the mamba TC kernel — bf16 mamba race
9	// configs ran the scalar L3 megakernel (the measured 905a4bb carve-out, TC 0.46×).
10	//
11	// This TU is the missing seam: it is globbed INTO _ops (no own pybind module), is
12	// compiled with -DSG_TUNED_GEMM_IMPL=1 (the in-source #define below) so it links the
13	// wgmma branch of fused_mamba_megakernel.cuh, and exposes ONE non-template host
14	// launcher whose boundary is plain pointers/ints + the FusedScalars POD — NO
15	// header-only types (MambaTokenCtx / FusedOptState) cross the boundary — so
16	// dispatch.cpp can extern-declare it with only the mirror structs it already has. It
17	// calls ONLY launch_fused_mamba_megakernel_tc (the TC launcher); it never
18	// instantiates the scalar launcher template, so it CANNOT collide (ODR/duplicate-
19	// symbol) with the scalar mega_mamba_real_adamw.cu TU even though both are in _ops.
20	// The TC activations/grad workspace is sized DIFFERENTLY from the scalar
21	// MambaScratch partials (mb_tc_workspace_floats), so this TU owns its own cached
22	// scratch internally — dispatch.cpp passes no workspace for the TC path.
23	//
24	// WHY MAMBA IS NOW ON THE TC PATH (owner cycle-2 directive (c)): mamba×adamw was
25	// excluded from _L3_WGMMA_CELLS as a measured scalar-WINS carve-out (0.46×, the
26	// selective-scan/conv1d dominate, not the projection GEMMs). That is a PERFORMANCE
27	// fact the roofline surfaces — NOT a correctness reason: the mamba TC kernel is
28	// validated 5/5 by tests/hw/test_mamba_tc.py. The directive lists mamba conversion
29	// explicitly, and no-suppression cuts toward exposing the path + letting the roofline
30	// report the (honest) 0.46×, rather than hiding a correct kernel. The scalar TU
31	// (mega_mamba_real_adamw.cu) is UNTOUCHED and remains the fp32 path; mamba×adamw at
32	// fp32 still routes there (gemm_impl_for_cell returns "scalar" for fp32).
33	//
34	// OPTID-GENERIC: identical to the decoder/vit TC launchers — the wgmma fwd+bwd is
35	// optimizer-independent, only the per-element tail (apply_optimizer<Opt>) differs.
36	// `opt_id` selects the kernel instantiation over the SAME [m|v|extra]+loss state
37	// buffer (ema = extra slice for grokfast; the neuralgrok psi-net pack would live at
38	// the head of extra). The STAGED/model-coupled/SG2 optimizers are NOT cases (no
39	// single-launch TC path); dispatch.cpp gates them out and an unsupported id returns
40	// cudaErrorInvalidValue → dispatch throws LOUD (no silent scalar/adamw fallback).
41	//
42	// HONESTY: this is the REAL bf16 wgmma path (HGMMA in SASS for the 4 projection
43	// GEMMs; the scan/conv stay scalar by design — REUSED verbatim), validated by
44	// tests/hw/test_mamba_tc.py.
45	
46	#define SG_TUNED_GEMM_IMPL 1   // select the wgmma cell driver (Fork-B TC branch)
47	
48	#include <cuda_runtime.h>
49	#include <cstdint>
50	#include "csrc/fused/sm_90/fused_mamba_megakernel.cuh"
51	
52	namespace sg { namespace fused { namespace sm90 {
53	
54	namespace {
55	// Persistent barrier/queue counters + the TC activations/grad workspace, cached
56	// per device. Mirrors mega_{decoder,vit}_real_adamw_tc_launcher.cu's scratch but
57	// for mamba's workspace shape. Raw cudaMalloc (process-lived scratch, recreated
58	// only when a larger B needs a bigger workspace; never freed — one per device,
59	// leaked at process exit like every cuBLAS/cuDNN handle).
60	struct MbTcLauncherScratch {
61	    int*      g_next = nullptr;        // int [1]
62	    unsigned* g_arrived = nullptr;     // unsigned [1]
63	    unsigned* g_generation = nullptr;  // unsigned [1]
64	    float*    workspace = nullptr;     // float [mb_tc_workspace_floats(T, nCTA)]
65	    int64_t   ws_floats = 0;
66	    int       dev = -1;
67	};
68	
69	MbTcLauncherScratch& mb_tc_launcher_scratch(int dev, int64_t need_floats) {
70	    static MbTcLauncherScratch s;
71	    if (s.dev != dev) {
72	        s.dev = dev;
73	        if (!s.g_next)       cudaMalloc(&s.g_next, sizeof(int));
74	        if (!s.g_arrived)    cudaMalloc(&s.g_arrived, sizeof(unsigned));
75	        if (!s.g_generation) cudaMalloc(&s.g_generation, sizeof(unsigned));
76	    }
77	    if (s.ws_floats < need_floats) {
78	        if (s.workspace) cudaFree(s.workspace);
79	        cudaMalloc(&s.workspace, (size_t)need_floats * sizeof(float));
80	        s.ws_floats = need_floats;
81	    }
82	    return s;
83	}
84	}  // anonymous namespace
85	
86	// mega_mamba_real_adamw_tc — the WIRED Mamba TC launcher. Boundary mirrors the scalar
87	// mega_mamba_real_adamw (dispatch.cpp extern-decls it with the same mirror types)
88	// EXCEPT it takes NO workspace pointer: the TC workspace is a different size from the
89	// scalar partials, so this TU allocates+owns it. `loss_out` still points into the
90	// caller's state[3*total] slot (dispatch reads it back). `opt_id` selects the tail.
91	//
92	// ncta_cap: forwarded to the TC launcher (0 = one CTA/SM = full saturation, the
93	// shipped config). The race always passes 0.
94	cudaError_t mega_mamba_real_adamw_tc(
95	        PersistentContext ctx, float* params,
96	        const int* tokens, const int* targets, int B,
97	        float* state, float* grad, float* /*workspace_unused*/, float* loss_out,
98	        float lr, int step, const FusedScalars& scalars, cudaStream_t stream,
99	        int ncta_cap, int opt_id) {
100	    const int64_t total = kMambaTotalElems;
101	    const int T = B * mb::kSeq;
102	
103	    int dev = 0;
104	    cudaError_t err = cudaGetDevice(&dev);
105	    if (err != cudaSuccess) return err;
106	    int n_sms = 1;
107	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
108	    if (err != cudaSuccess) return err;
109	    int nCTA = n_sms;
110	    if (ncta_cap > 0 && ncta_cap < nCTA) nCTA = ncta_cap;
111	
112	    const int64_t need = mb_tc_workspace_floats(T, nCTA);
113	    MbTcLauncherScratch& sc = mb_tc_launcher_scratch(dev, need);
114	
115	    // Re-point the ctx counters at THIS TU's cached counters (the TC launcher zeroes
116	    // them per-launch, but they must be the ones this scratch owns so the grid
117	    // barrier is consistent with the workspace).
118	    ctx.g_next_task  = sc.g_next;
119	    ctx.g_arrived    = sc.g_arrived;
120	    ctx.g_generation = sc.g_generation;
121	    ctx.n_tasks      = kMambaNumTensors;   // parameter tensors for reduce+opt phases
122	
123	    // Bind the optimizer state slices. [m | v | extra] over the SAME state buffer;
124	    // each tail reads only its own buffers (opt_components.cuh guarantees unused
125	    // pointers are never dereferenced). ema/psi-net live in the `extra` slice.
126	    float* const extra_slice = state + 2 * total;
127	    FusedOptState st;
128	    st.exp_avg    = state;
129	    st.exp_avg_sq = state + total;
130	    st.ema        = extra_slice;          // grokfast/grokadamw slow-grad EMA
131	    st.psi_W1     = extra_slice + kPsiW1Off;   // neuralgrok psi-net pack (when wired)
132	    st.psi_b1     = extra_slice + kPsiB1Off;
133	    st.psi_W2     = extra_slice + kPsiW2Off;
134	    apply_scalars(st, scalars);   // FULL scalar set (un-frozen bc1/bc2/...)
135	    st.lr = lr;
136	
137	    MambaTokenCtx tok;
138	    tok.tokens    = tokens;
139	    tok.targets   = targets;
140	    tok.B         = B;
141	    tok.workspace = sc.workspace;
142	    tok.loss_out  = loss_out;
143	
144	    // Dispatch to the matching kernel instantiation. The fwd+bwd is identical across
145	    // these OptIds; the template differs ONLY in the P3 apply_optimizer<Opt> tail.
146	    // Unsupported opt_ids return cudaErrorInvalidValue → dispatch.cpp throws LOUD.
147	    switch (static_cast<OptId>(opt_id)) {
148	        case OptId::AdamW:
149	            return launch_fused_mamba_megakernel_tc<OptId::AdamW>(
150	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
151	        case OptId::Lion:
152	            return launch_fused_mamba_megakernel_tc<OptId::Lion>(
153	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
154	        case OptId::Grokfast:
155	            return launch_fused_mamba_megakernel_tc<OptId::Grokfast>(
156	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
157	        default:
158	            return cudaErrorInvalidValue;  // STAGED/coupled opt not single-launch TC
159	    }
160	}
161	
162	}}}  // namespace sg::fused::sm90
