// Standalone PROFILING TU for the mamba TC megakernel — defines SG_MB_TC_PROFILE
// so the kernel brackets P1-fwd/P1-bwd/P2/P3 with clock64() into the workspace
// tail. Mirrors mega_mamba_real_adamw_tc.cu's tc_train_step but reads back the
// per-CTA cycle accumulators. NOT shipped; /tmp only.
#define SG_TUNED_GEMM_IMPL 1
#define SG_MB_TC_PROFILE 1
#include <cuda_runtime.h>
#include <torch/extension.h>
#include <vector>
#include "csrc/fused/sm_90/fused_mamba_megakernel.cuh"

using namespace sg::fused::sm90;

static torch::Tensor g_next, g_arr, g_gen, g_ws;
static int64_t g_ws_floats = 0;

static std::vector<torch::Tensor> prof_train_step(
        torch::Tensor params, torch::Tensor tokens, torch::Tensor targets,
        torch::Tensor state, double lr, int64_t ncta_cap) {
    const int B = (int)targets.numel();
    const int64_t total = kMambaTotalElems;
    const int T = B * mb::kSeq;
    int dev = params.get_device();
    int n_sms = 1; cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
    int nCTA = n_sms;
    if (ncta_cap > 0 && (int)ncta_cap < nCTA) nCTA = (int)ncta_cap;

    const int64_t need = mb_tc_workspace_floats(T, nCTA);
    if (!g_next.defined()) {
        auto oi = torch::dtype(torch::kInt32).device(params.device());
        g_next = torch::zeros({1}, oi); g_arr = torch::zeros({1}, oi); g_gen = torch::zeros({1}, oi);
    }
    if (g_ws_floats < need) { g_ws = torch::zeros({need}, torch::dtype(torch::kFloat32).device(params.device())); g_ws_floats = need; }
    // zero the profiling tail every call (it accumulates).
    g_ws.zero_();
    auto grad = torch::zeros({total}, torch::dtype(torch::kFloat32).device(params.device()));
    auto loss_dev = torch::zeros({1}, torch::dtype(torch::kFloat32).device(params.device()));

    PersistentContext ctx{ g_next.data_ptr<int>(),
        reinterpret_cast<unsigned*>(g_arr.data_ptr<int>()),
        reinterpret_cast<unsigned*>(g_gen.data_ptr<int>()), kMambaNumTensors, 0u };

    FusedOptState st; float* m = state.data_ptr<float>();
    st.exp_avg = m; st.exp_avg_sq = m + total;
    st.lr=(float)lr; st.beta1=0.9f; st.beta2=0.98f; st.eps=1e-8f; st.wd=0.f; st.bc1=0.1f; st.bc2=0.02f;

    MambaTokenCtx tok; tok.tokens=tokens.data_ptr<int>(); tok.targets=targets.data_ptr<int>();
    tok.B=B; tok.workspace=g_ws.data_ptr<float>(); tok.loss_out=loss_dev.data_ptr<float>();

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    cudaError_t err = launch_fused_mamba_megakernel_tc<OptId::AdamW>(
        ctx, params.data_ptr<float>(), tok, grad.data_ptr<float>(), (float)lr, 1, st, stream, nCTA);
    TORCH_CHECK(err==cudaSuccess, "prof launch failed: ", cudaGetErrorString(err));
    C10_CUDA_CHECK(cudaStreamSynchronize(stream));

    // profiling buffer = doubles at float-offset (acts + nCTA*scratch + nCTA*part + nCTA + 1)
    const int64_t prof_foff = mb_tc_acts_floats(T)
        + (int64_t)nCTA * mbtc::mb_tile_scratch_floats()
        + (int64_t)nCTA * mbtc::kPartElems + nCTA + 1;
    // doubles overlay floats: nCTA*SLOTS doubles = nCTA*SLOTS*2 floats
    auto prof = g_ws.slice(0, prof_foff, prof_foff + (int64_t)nCTA*SG_MBTC_PROF_SLOTS*2)
                    .view(torch::kFloat64).to(torch::kCPU);
    return {loss_dev.to(torch::kCPU), prof, torch::tensor({(int64_t)nCTA})};
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("prof_train_step", &prof_train_step);
    m.attr("TOTAL") = (int)kMambaTotalElems;
    m.attr("SLOTS") = (int)SG_MBTC_PROF_SLOTS;
}

