// Per-element (flat slab index → grad base offset) map for the FLAT-PARALLEL
// reduce below. The slab is the contiguous concatenation of the kNumPartTensors
// partial tensors (the SAME order mbtc_part_slot enumerates), so a flat slab index
// `e` falls in exactly one tensor segment [part_off_v, part_off_v+numel_v); its
// grad destination is kMambaOffsets[grad_idx_v] + (e - part_off_v). We build the
// segment boundary table once per call (16 entries, cheap) and linear-scan it; the
// scan is warp-coherent because consecutive e share a tensor for long runs.
struct MbPartSegTable {
    int64_t seg_start[kNumPartTensors + 1];   // slab start of each tensor; [n] = kPartElems
    int64_t gbase[kNumPartTensors];           // grad base offset of each tensor
};
__device__ __forceinline__ void mbtc_part_build_segtable(MbPartSegTable& tbl) {
    int64_t acc = 0;
    #pragma unroll
    for (int v = 0; v < kNumPartTensors; ++v) {
        int grad_idx, numel; int64_t part_off;
        mbtc_part_slot(v, grad_idx, part_off, numel);
        tbl.seg_start[v] = part_off;           // (== acc; monotonic, contiguous)
        tbl.gbase[v] = kMambaOffsets[grad_idx];
        acc = part_off + numel;
    }
    tbl.seg_start[kNumPartTensors] = acc;       // == kPartElems
}

// FLAT-PARALLEL cross-CTA reduce: stripe the kPartElems flat slab elements across
// ALL nCTA CTAs × blockDim threads (not the old by-tensor split that left only
// kNumPartTensors=16 of 132 CTAs working while 116 idled at the B2 barrier — the
// measured ~19%-of-wall straggler). Each flat element e is summed across the nCTA
// per-CTA partials in ASCENDING c (deterministic, unchanged) and scattered to its
// grad tensor via the segment table. Element ownership is a fixed function of e, so
// the reduce stays bit-identical across runs (gate-2 A/A/A).
__device__ __forceinline__ void mbtc_partial_reduce(
        const float* __restrict__ part_base, float* __restrict__ grad,
        int nCTA, int cta) {
    __shared__ MbPartSegTable tbl;
    if (threadIdx.x == 0) mbtc_part_build_segtable(tbl);
    __syncthreads();
    const int64_t stride = (int64_t)nCTA * blockDim.x;
    int seg = 0;
    for (int64_t e = (int64_t)cta * blockDim.x + threadIdx.x; e < kPartElems; e += stride) {
        // advance/reset the cached segment to the one containing e (linear scan;
        // warp-coherent for long runs — only steps at tensor boundaries).
        if (e < tbl.seg_start[seg] || e >= tbl.seg_start[seg + 1]) {
            seg = 0;
            while (e >= tbl.seg_start[seg + 1]) ++seg;
        }
        float accv = 0.0f;
        for (int c = 0; c < nCTA; ++c)
            accv += part_base[(int64_t)c * kPartElems + e];
        grad[tbl.gbase[seg] + (e - tbl.seg_start[seg])] = accv;
    }
}

