  if(gWf<need){gW=torch::zeros({need},torch::dtype(torch::kFloat32).device(params.device()));gWf=need;}
  auto grad=torch::zeros({total},torch::dtype(torch::kFloat32).device(params.device()));
  auto lo=torch::zeros({1},torch::dtype(torch::kFloat32).device(params.device()));
