}

def build(name, defs):
    src=TU_SRC.replace("{DEFS}", defs)
    p=f"/tmp/diff_{name}.cu"; open(p,"w").write(src)
    return load(name=f"diff_{name}", sources=[p], extra_include_paths=[ROOT],
        extra_cuda_cflags=["-O3","-std=c++17","--expt-relaxed-constexpr",
        "-gencode=arch=compute_90a,code=sm_90a","-gencode=arch=compute_90a,code=compute_90a"],
        extra_cflags=["-O3","-std=c++17"], verbose=False)

def timeit(fn,w=20,n=30,reps=5):
    for _ in range(w): fn()
    torch.cuda.synchronize(); best=1e30
    for _ in range(reps):
