// Standalone direct-launcher tail gate for mamba×{AdamW,Lion,Grokfast} — the exact
// (gate-1 tail-parity + gate-2 A/A/A determinism) pair the mandated
// test_l3tc_tail_gate.py checks, but calling launch_fused_mamba_megakernel_tc<Opt>
// directly (bypassing the sibling-blocked _ops dispatch import). occ=1 default.
#define SG_TUNED_GEMM_IMPL 1
#include <torch/extension.h>
#include <c10/cuda/CUDAStream.h>
#include <c10/cuda/CUDAException.h>
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <cstdint>
#include <vector>
#include "csrc/fused/sm_90/fused_mamba_megakernel.cuh"
using namespace sg::fused; using namespace sg::fused::sm90;

static torch::Tensor gN,gA,gG,gW; static int64_t gWf=0;

// One TC step for a given opt_id. Returns {loss, reduced_grad, updated_params}.
// state = [m|v|extra] (extra holds grokfast ema). scalars set per the gate factories.
static std::vector<torch::Tensor> step(int opt_id, torch::Tensor params, torch::Tensor tok,
        torch::Tensor tgt, torch::Tensor state, double lr, double beta1, double beta2,
        double eps, double wd, double bc1, double bc2,
        double gf_alpha, double gf_lamb, int stepn) {
    const int B=(int)tgt.numel(); const int64_t total=kMambaTotalElems; const int T=B*mb::kSeq;
    int dev=params.get_device(); int nsm=1; cudaDeviceGetAttribute(&nsm,cudaDevAttrMultiProcessorCount,dev);
    int nCTA=mb_tc_launched_nctas<OptId::AdamW>(dev,0); if(nCTA<=0) nCTA=nsm;
    const int64_t need=mb_tc_workspace_floats(T,nCTA);
    if(!gN.defined()){auto oi=torch::dtype(torch::kInt32).device(params.device()); gN=torch::zeros({1},oi);gA=torch::zeros({1},oi);gG=torch::zeros({1},oi);}
    if(gWf<need){gW=torch::zeros({need},torch::dtype(torch::kFloat32).device(params.device()));gWf=need;}
    auto p=params.clone();
    auto grad=torch::zeros({total},torch::dtype(torch::kFloat32).device(params.device()));
    auto lo=torch::zeros({1},torch::dtype(torch::kFloat32).device(params.device()));
    PersistentContext ctx{gN.data_ptr<int>(),reinterpret_cast<unsigned*>(gA.data_ptr<int>()),reinterpret_cast<unsigned*>(gG.data_ptr<int>()),kMambaNumTensors,0u};
    FusedOptState st; float* m=state.data_ptr<float>();
    st.exp_avg=m; st.exp_avg_sq=m+total; st.ema=m+2*total;
    st.lr=(float)lr;st.beta1=(float)beta1;st.beta2=(float)beta2;st.eps=(float)eps;st.wd=(float)wd;
    st.bc1=(float)bc1;st.bc2=(float)bc2;
    st.grokfast_alpha=(float)gf_alpha; st.grokfast_lamb=(float)gf_lamb;
    MambaTokenCtx tk; tk.tokens=tok.data_ptr<int>();tk.targets=tgt.data_ptr<int>();tk.B=B;tk.workspace=gW.data_ptr<float>();tk.loss_out=lo.data_ptr<float>();
    cudaStream_t s=c10::cuda::getCurrentCUDAStream().stream();
    cudaError_t e;
    switch((OptId)opt_id){
      case OptId::AdamW: e=launch_fused_mamba_megakernel_tc<OptId::AdamW>(ctx,p.data_ptr<float>(),tk,grad.data_ptr<float>(),(float)lr,stepn,st,s,0); break;
      case OptId::Lion:  e=launch_fused_mamba_megakernel_tc<OptId::Lion >(ctx,p.data_ptr<float>(),tk,grad.data_ptr<float>(),(float)lr,stepn,st,s,0); break;
      case OptId::Grokfast: e=launch_fused_mamba_megakernel_tc<OptId::Grokfast>(ctx,p.data_ptr<float>(),tk,grad.data_ptr<float>(),(float)lr,stepn,st,s,0); break;
      default: e=cudaErrorInvalidValue;
    }
    TORCH_CHECK(e==cudaSuccess,"launch failed: ",cudaGetErrorString(e)); C10_CUDA_CHECK(cudaStreamSynchronize(s));
    return {lo.to(torch::kCPU), grad, p};
}
PYBIND11_MODULE(TORCH_EXTENSION_NAME,m){ m.def("step",&step); m.attr("TOTAL")=(int)kMambaTotalElems; }

