__device__ __forceinline__ void lion_step(
    ParamT* __restrict__ param,
    float* __restrict__ exp_avg,
    const GradT* __restrict__ grad,
    const float lr,
    const float beta1,
    const float beta2,
    const float wd,
    const int64_t idx
) {
    const float g  = static_cast<float>(grad[idx]);
    const float ea = exp_avg[idx];
